head.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());

gtag('config', 'G-DC2GR9XDCS');

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page {
  display: inline-block;
  vertical-align: top;
  width: 55%;
}
body#layout .sidebar-container {
  display: inline-block;
  float: right;
  width: 40%;
}
body#layout .hamburger-menu,
body#layout .search {
  display: none;
}

body.script:
//
document.addEventListener("DOMContentLoaded", function() {
  var pageList = document.querySelector(".PageList ul");
  if (!pageList) return;

  var items = Array.from(pageList.children);
  var currentParent = null;

  items.forEach(function(item) {
    if (item.tagName.toLowerCase() !== "li") return;

    var link = item.querySelector("a");
    if (!link) return;

    var text = link.textContent.trim();

    // चेक करें कि नाम में अण्डरस्कोर _ लगा है या नहीं
    if (text.startsWith("_")) {
      link.textContent = text.replace(/^_\s*/, "");

      if (currentParent) {
        var submenu = currentParent.querySelector("ul.submenu");
        if (!submenu) {
          submenu = document.createElement("ul");
          submenu.className = "submenu";
          currentParent.appendChild(submenu);

          var parentLink = currentParent.querySelector("a");
          if (parentLink && !parentLink.querySelector(".arrow-icon")) {
            var arrow = document.createElement("span");
            arrow.className = "arrow-icon";
            arrow.innerHTML = "▼";
            parentLink.appendChild(arrow);

            // क्लिक करने पर ड्रॉपडाउन टॉगल करना
            parentLink.addEventListener("click", function(e) {
              if (parentLink.getAttribute("href") === "#" || window.innerWidth <= 768) {
                e.preventDefault();
                currentParent.classList.toggle("open");
              }
            });
          }
        }
        submenu.appendChild(item);
      }
    } else {
      currentParent = item;
    }
  });

  // बाहर कहीं भी टच करने पर ड्रॉपडाउन बंद हो जाए
  document.addEventListener("click", function(e) {
    if (!e.target.closest(".PageList")) {
      document.querySelectorAll(".PageList li.open").forEach(function(li) {
        li.classList.remove("open");
      });
    }
  });
});
//
